7	export async function validateSkill(skill, schemaPath) {
8	  const errors = [];
9	
10	  if (skill.error === "missing-meta") {
11	    errors.push(`${path.basename(skill.dir)}: missing skill.meta.json`);
12	    return errors;
13	  }
14	  if (skill.error === "missing-skill-md") {
15	    errors.push(`${path.basename(skill.dir)}: missing SKILL.md`);
16	    return errors;
17	  }
18	  if (skill.error === "invalid-meta-json") {
19	    errors.push(`${path.basename(skill.dir)}: invalid JSON in skill.meta.json`);
20	    return errors;
21	  }
22	
23	  const schemaContent = await fs.readFile(schemaPath, "utf-8");
24	  const schema = JSON.parse(schemaContent);
25	  const ajv = new Ajv({ allErrors: true });
26	  const validate = ajv.compile(schema);
27	  const valid = validate(skill.meta);
28	
29	  if (!valid) {
30	    for (const err of validate.errors) {
31	      errors.push(`${skill.meta.slug}: schema error at ${err.instancePath || "/"}: ${err.message}`);
32	    }
33	  }
34	
35	  if (skill.frontmatter && skill.meta) {
36	    if (skill.frontmatter.name !== skill.meta.slug) {
37	      errors.push(
38	        `Slug mismatch in '${path.basename(skill.dir)}': ` +
39	          `skill.meta.json slug='${skill.meta.slug}' != SKILL.md name='${skill.frontmatter.name}'`
40	      );
41	    }
42	  }
43	
44	  return errors;
45	}
