47	export function validateConstraints(skills) {
48	  const errors = [];
49	  const bySlug = new Map();
50	  for (const s of skills) {
51	    bySlug.set(s.meta.slug, s);
52	  }
53	
54	  for (const skill of skills) {
55	    const { slug, tier, depends_on = [], platform } = skill.meta;
56	
57	    if (tier === "atom" && depends_on.length > 0) {
58	      errors.push(`ERROR: Atom '${slug}' must not have dependencies (has: ${depends_on.join(", ")})`);
59	    }
60	
61	    for (const dep of depends_on) {
62	      const depSkill = bySlug.get(dep);
63	      if (!depSkill) {
64	        errors.push(`ERROR: '${slug}' depends on unknown skill '${dep}'`);
65	        continue;
66	      }
67	
68	      if (tier === "molecule" && depSkill.meta.tier !== "atom") {
69	        errors.push(`ERROR: Molecule '${slug}' depends on non-atom '${dep}' (tier: ${depSkill.meta.tier})`);
70	      }
71	      if (tier === "compound" && depSkill.meta.tier !== "molecule") {
72	        errors.push(`ERROR: Compound '${slug}' depends on non-molecule '${dep}' (tier: ${depSkill.meta.tier})`);
73	      }
74	
75	      if (platform === "gitlab" && depSkill.meta.platform === "github") {
76	        errors.push(`ERROR: '${slug}' (gitlab) depends on '${dep}' (github)`);
77	      }
78	      if (platform === "github" && depSkill.meta.platform === "gitlab") {
79	        errors.push(`ERROR: '${slug}' (github) depends on '${dep}' (gitlab)`);
80	      }
81	    }
82	  }
83	
84	  const cycleErrors = detectCycles(skills);
85	  errors.push(...cycleErrors);
86	
87	  return errors;
88	}
89	
90	function detectCycles(skills) {
91	  const errors = [];
92	  const inDegree = new Map();
93	  const adj = new Map();
94	
95	  for (const s of skills) {
96	    const slug = s.meta.slug;
97	    if (!inDegree.has(slug)) inDegree.set(slug, 0);
98	    if (!adj.has(slug)) adj.set(slug, []);
99	  }
100	
101	  for (const s of skills) {
102	    const dependsOn = s.meta.depends_on || [];
103	    for (const dep of dependsOn) {
104	      if (!adj.has(dep)) continue;
105	      adj.get(dep).push(s.meta.slug);
106	      inDegree.set(s.meta.slug, (inDegree.get(s.meta.slug) || 0) + 1);
107	    }
108	  }
109	
110	  const queue = [];
111	  for (const [slug, degree] of inDegree) {
112	    if (degree === 0) queue.push(slug);
113	  }
114	
115	  let visited = 0;
116	  while (queue.length > 0) {
117	    const slug = queue.shift();
118	    visited++;
119	    for (const neighbor of adj.get(slug) || []) {
120	      const newDegree = inDegree.get(neighbor) - 1;
121	      inDegree.set(neighbor, newDegree);
122	      if (newDegree === 0) queue.push(neighbor);
123	    }
124	  }
125	
126	  if (visited < skills.length) {
127	    const cycled = skills
128	      .filter((s) => inDegree.get(s.meta.slug) > 0)
129	      .map((s) => s.meta.slug);
130	    errors.push(`ERROR: Circular dependency detected involving: ${cycled.join(", ")}`);
131	  }
132	
133	  return errors;
134	}
