136	export async function runValidate(rootPath) {
137	  const resolvedPath = path.resolve(rootPath);
138	
139	  let skillsRoot = resolvedPath;
140	  const opencodePath = path.join(resolvedPath, ".opencode", "skills");
141	  try {
142	    await fs.access(opencodePath);
143	    skillsRoot = opencodePath;
144	  } catch {
145	    // Use rootPath as-is
146	  }
147	
148	  const schemaPath = findSchemaPath(resolvedPath);
149	
150	  console.log(`Scanning: ${skillsRoot}`);
151	  const skills = await discoverSkills(skillsRoot);
152	
153	  if (skills.length === 0) {
154	    console.log("No skills found.");
155	    return 1;
156	  }
157	
158	  console.log(`Found ${skills.length} skill(s)\n`);
159	
160	  let allErrors = [];
161	
162	  for (const skill of skills) {
163	    const errors = await validateSkill(skill, schemaPath);
164	    if (errors.length > 0) {
165	      allErrors.push(...errors);
166	    }
167	  }
168	
169	  const validSkills = skills.filter((s) => s.meta && !validateSkillMetaShape(s.meta));
170	  const constraintErrors = validateConstraints(validSkills);
171	  allErrors.push(...constraintErrors);
172	
173	  if (allErrors.length === 0) {
174	    console.log("✓ All validations passed.");
175	    return 0;
176	  }
177	
178	  console.log(`Found ${allErrors.length} error(s):\n`);
