185	function findSchemaPath(rootPath) {
186	  const candidates = [
187	    path.join(rootPath, "schemas", "skill-meta.schema.json"),
188	    path.resolve(rootPath, "..", "schemas", "skill-meta.schema.json"),
189	    path.resolve(rootPath, "..", "..", "schemas", "skill-meta.schema.json"),
190	    path.resolve(rootPath, "..", "..", "..", "schemas", "skill-meta.schema.json"),
191	    path.resolve(rootPath, "..", "..", "..", "..", "schemas", "skill-meta.schema.json"),
192	  ];
193	  return candidates.find((candidate) => existsSync(candidate)) || candidates[0];
194	}
