4	export function parseFrontmatter(content) {
5	  const match = content.match(/^---\n([\s\S]*?)\n---/);
6	  if (!match) return null;
7	  const result = {};
8	  for (const line of match[1].split("\n")) {
9	    const colonIdx = line.indexOf(":");
10	    if (colonIdx === -1) continue;
11	    const key = line.slice(0, colonIdx).trim();
12	    let value = line.slice(colonIdx + 1).trim();
13	    if (
14	      (value.startsWith('"') && value.endsWith('"')) ||
15	      (value.startsWith("'") && value.endsWith("'"))
16	    ) {
17	      value = value.slice(1, -1);
18	    }
19	    result[key] = value;
20	  }
21	  return result;
22	}
