24	export async function loadSkill(skillDir) {
25	  const skillMdPath = path.join(skillDir, "SKILL.md");
26	  const metaPath = path.join(skillDir, "skill.meta.json");
27	  let frontmatter = null;
28	  try {
29	    const content = await fs.readFile(skillMdPath, "utf-8");
30	    frontmatter = parseFrontmatter(content);
31	  } catch {
32	    return { dir: skillDir, frontmatter: null, error: "missing-skill-md" };
33	  }
34	  let meta = null;
35	  try {
36	    const raw = await fs.readFile(metaPath, "utf-8");
37	    meta = JSON.parse(raw);
38	  } catch (err) {
39	    if (err.code === "ENOENT") {
40	      return { dir: skillDir, frontmatter, error: "missing-meta" };
41	    }
42	    return { dir: skillDir, frontmatter, error: "invalid-meta-json" };
43	  }
44	  return { dir: skillDir, meta, frontmatter };
45	}
