47	export async function discoverSkills(rootDir) {
48	  const skills = [];
49	  const tierDirs = ["atoms", "molecules", "compounds"];
50	  for (const tier of tierDirs) {
51	    const tierPath = path.join(rootDir, tier);
52	    try {
53	      const entries = await fs.readdir(tierPath, { withFileTypes: true });
54	      for (const entry of entries) {
55	        if (!entry.isDirectory()) continue;
56	        const skillDir = path.join(tierPath, entry.name);
57	        if (await hasSkillMd(skillDir)) {
58	          skills.push(await loadSkill(skillDir));
59	        }
60	      }
61	    } catch { /* tier dir doesn't exist */ }
62	  }
63	  try {
64	    const entries = await fs.readdir(rootDir, { withFileTypes: true });
65	    for (const entry of entries) {
66	      if (!entry.isDirectory()) continue;
67	      if (tierDirs.includes(entry.name)) continue;
68	      const skillDir = path.join(rootDir, entry.name);
69	      if (await hasSkillMd(skillDir)) {
70	        skills.push(await loadSkill(skillDir));
71	      }
72	    }
73	  } catch { /* root doesn't exist */ }
74	  return skills;
75	}
