5	const TIER_STYLES = {
6	  atom: { mermaid: "([%s])", dot: 'shape=ellipse, style=filled, fillcolor="#d4edda"' },
7	  molecule: { mermaid: "[%s]", dot: 'shape=box, style=filled, fillcolor="#cce5ff"' },
8	  compound: { mermaid: "[[%s]]", dot: 'shape=box3d, style=filled, fillcolor="#fff3cd"' },
9	};
