11	export function generateMermaid(skills, { tier } = {}) {
12	  let filtered = skills;
13	  if (tier) {
14	    filtered = skills.filter((s) => s.meta.tier === tier);
15	  }
16	
17	  const lines = ["graph TD"];
18	
19	  for (const s of filtered) {
20	    const style = TIER_STYLES[s.meta.tier] || TIER_STYLES.molecule;
21	    const shape = style.mermaid.replace("%s", `"${s.meta.slug}"`);
22	    lines.push(`  ${s.meta.slug}${shape}`);
23	  }
24	
25	  const slugSet = new Set(filtered.map((s) => s.meta.slug));
26	  for (const s of filtered) {
27	    for (const dep of s.meta.depends_on) {
28	      if (slugSet.has(dep)) {
29	        lines.push(`  ${s.meta.slug} --> ${dep}`);
30	      }
31	    }
32	  }
33	
34	  for (const [tierName, _style] of Object.entries(TIER_STYLES)) {
35	    const tierSkills = filtered.filter((s) => s.meta.tier === tierName);
36	    if (tierSkills.length > 0) {
37	      lines.push(`  subgraph ${tierName}s`);
38	      for (const s of tierSkills) {
39	        lines.push(`    ${s.meta.slug}`);
40	      }
41	      lines.push("  end");
42	    }
43	  }
44	
45	  return lines.join("\n");
46	}
