48	export function generateDot(skills, { tier } = {}) {
49	  let filtered = skills;
50	  if (tier) {
51	    filtered = skills.filter((s) => s.meta.tier === tier);
52	  }
53	
54	  const lines = ["digraph skills {", "  rankdir=BT;", "  node [fontname=Helvetica];"];
55	
56	  for (const s of filtered) {
57	    const style = TIER_STYLES[s.meta.tier] || TIER_STYLES.molecule;
58	    lines.push(`  "${s.meta.slug}" [${style.dot}, label="${s.meta.slug}"];`);
59	  }
60	
61	  const slugSet = new Set(filtered.map((s) => s.meta.slug));
62	  for (const s of filtered) {
63	    for (const dep of s.meta.depends_on) {
64	      if (slugSet.has(dep)) {
65	        lines.push(`  "${s.meta.slug}" -> "${dep}";`);
66	      }
67	    }
68	  }
69	
70	  lines.push("}");
71	  return lines.join("\n");
72	}
