74	export function buildDepTree(skills, slug) {
75	  const bySlug = new Map();
76	  for (const s of skills) {
77	    bySlug.set(s.meta.slug, s);
78	  }
79	
80	  function build(currentSlug, visited = new Set()) {
81	    const s = bySlug.get(currentSlug);
82	    if (!s) return null;
83	    if (visited.has(currentSlug)) return { slug: currentSlug, tier: s.meta.tier, children: [], circular: true };
84	    visited.add(currentSlug);
85	
86	    const children = s.meta.depends_on
87	      .map((dep) => build(dep, new Set(visited)))
88	      .filter(Boolean);
89	
90	    return { slug: currentSlug, tier: s.meta.tier, children };
91	  }
92	
93	  return build(slug);
94	}
