96	function formatTree(node, indent = 0) {
97	  const prefix = "  ".repeat(indent);
98	  const marker = indent === 0 ? "" : "└─ ";
99	  let output = `${prefix}${marker}${node.slug} (${node.tier})${node.circular ? " [CIRCULAR]" : ""}\n`;
100	  for (const child of node.children) {
101	    output += formatTree(child, indent + 1);
102	  }
103	  return output;
104	}
