16	export function buildSkillTable(skills) {
17	  const headers = ["Slug", "Tier", "Platform", "Version", "Deps", "Description"];
18	  const rows = skills.map((s) => [
19	    s.meta.slug,
20	    s.meta.tier,
21	    s.meta.platform,
22	    s.meta.version,
23	    s.meta.depends_on.length.toString(),
24	    s.meta.description.slice(0, 50),
25	  ]);
26	
27	  const widths = headers.map((h, i) =>
28	    Math.max(h.length, ...rows.map((r) => r[i].length))
29	  );
30	
31	  const sep = widths.map((w) => "-".repeat(w)).join(" | ");
32	  const headerLine = headers.map((h, i) => h.padEnd(widths[i])).join(" | ");
33	  const dataLines = rows.map((r) =>
34	    r.map((cell, i) => cell.padEnd(widths[i])).join(" | ")
35	  );
36	
37	  return [headerLine, sep, ...dataLines].join("\n");
38	}
