3	/**
4	 * bundle-assets.js
5	 *
6	 * Copies skill files, command assets, memory-init templates, JSON schemas,
7	 * and workflow schemas from the repo
8	 * source-of-truth locations into the package's assets/ directory for distribution.
9	 *
10	 * Run as part of prepublishOnly: npm run build && node scripts/bundle-assets.js
11	 *
12	 * Asset sources:
13	 *   .opencode/skills/<tier>/corgispec-*  → assets/skills/<tier>/
14	 *   .opencode/commands/*.md      → assets/commands/opencode/
15	 *   .claude/commands/corgi/*.md   → assets/commands/claude/corgi/
16	 *   .opencode/skills/corgispec-memory-init/templates/** → assets/memory-init/templates/
17	 *   schemas/                     → assets/schemas/ (JSON Schema files for validation)
18	 *   openspec/schemas/            → assets/schemas/ (workflow schemas for init/doctor)
19	 */
20	
21	import { cpSync, mkdirSync, rmSync, existsSync, readdirSync, readFileSync } from "node:fs";
22	import { resolve, dirname } from "node:path";
23	import { fileURLToPath } from "node:url";
24	import { createHash } from "node:crypto";
25	
26	const __dirname = dirname(fileURLToPath(import.meta.url));
27	const packageRoot = resolve(__dirname, "..");
28	const repoRoot = resolve(packageRoot, "../..");
29	
30	const assetsDir = process.env.CORGISPEC_ASSETS_DIR
31	  ? resolve(process.env.CORGISPEC_ASSETS_DIR)
32	  : resolve(packageRoot, "assets");
33	
34	// --- Clean and recreate assets directory ---
35	if (existsSync(assetsDir)) {
36	  rmSync(assetsDir, { recursive: true });
37	}
38	mkdirSync(assetsDir, { recursive: true });
39	
40	let totalFiles = 0;
41	const errors = [];
42	
43	function copyMarkdownFiles(sourceDir, destDir) {
44	  mkdirSync(destDir, { recursive: true });
45	
46	  if (!existsSync(sourceDir)) {
47	    return 0;
48	  }
49	
50	  const files = readdirSync(sourceDir).filter((file) => file.endsWith(".md"));
51	  for (const file of files) {
52	    cpSync(resolve(sourceDir, file), resolve(destDir, file));
53	  }
54	
55	  return files.length;
56	}
57	
58	// --- 1. Bundle skills from .opencode/skills/ (tiered: atoms/, molecules/, compounds/, + flat root) ---
59	const skillsSource = resolve(repoRoot, ".opencode/skills");
60	const skillsDest = resolve(assetsDir, "skills");
61	mkdirSync(skillsDest, { recursive: true });
62	
63	const tierDirs = ["atoms", "molecules", "compounds"];
64	
65	function bundleSkillEntry(entry, parentDir, tier) {
66	  if (!entry.isDirectory() || !entry.name.startsWith("corgispec-")) return false;
67	  const src = resolve(parentDir, entry.name);
68	  const destParent = tier ? resolve(skillsDest, tier) : skillsDest;
69	  mkdirSync(destParent, { recursive: true });
70	  const dest = resolve(destParent, entry.name);
71	  cpSync(src, dest, { recursive: true });
72	
73	  if (!existsSync(resolve(dest, "SKILL.md"))) {
74	    errors.push(`${entry.name}: missing SKILL.md`);
75	  }
76	  if (!existsSync(resolve(dest, "skill.meta.json"))) {
77	    errors.push(`${entry.name}: missing skill.meta.json`);
78	  }
79	  return true;
80	}
81	
82	if (existsSync(skillsSource)) {
83	  let skillCount = 0;
84	
85	  // Scan tiered subdirectories first
86	  for (const tier of tierDirs) {
87	    const tierPath = resolve(skillsSource, tier);
88	    if (!existsSync(tierPath)) continue;
89	    const entries = readdirSync(tierPath, { withFileTypes: true });
90	    for (const entry of entries) {
91	      if (bundleSkillEntry(entry, tierPath, tier)) skillCount++;
92	    }
93	  }
94	
95	  // Scan root for any remaining flat skills (backward compat)
96	  const rootEntries = readdirSync(skillsSource, { withFileTypes: true });
97	  for (const entry of rootEntries) {
98	    if (tierDirs.includes(entry.name)) continue;
99	    if (bundleSkillEntry(entry, skillsSource, null)) skillCount++;
100	  }
101	
102	  totalFiles += skillCount;
103	  console.log(`✓ Bundled ${skillCount} skills from ${skillsSource}`);
104	} else {
105	  errors.push(`Skills source not found at ${skillsSource}`);
106	}
107	
108	// --- 2. Bundle project-local command assets ---
109	const opencodeCommandsSource = resolve(repoRoot, ".opencode/commands");
110	const opencodeCommandsDest = resolve(assetsDir, "commands/opencode");
111	const claudeCommandsSource = resolve(repoRoot, ".claude/commands/corgi");
112	const claudeCommandsDest = resolve(assetsDir, "commands/claude/corgi");
113	
114	if (existsSync(opencodeCommandsSource)) {
115	  const commandCount = copyMarkdownFiles(opencodeCommandsSource, opencodeCommandsDest);
116	  totalFiles += commandCount;
117	  console.log(`✓ Bundled ${commandCount} OpenCode command(s) from ${opencodeCommandsSource}`);
118	} else {
119	  errors.push(`OpenCode commands source not found at ${opencodeCommandsSource}`);
120	}
121	
122	if (existsSync(claudeCommandsSource)) {
123	  const commandCount = copyMarkdownFiles(claudeCommandsSource, claudeCommandsDest);
124	  totalFiles += commandCount;
125	  console.log(`✓ Bundled ${commandCount} Claude command(s) from ${claudeCommandsSource}`);
126	} else {
127	  errors.push(`Claude commands source not found at ${claudeCommandsSource}`);
128	}
129	
130	// --- 3. Bundle corgispec-memory-init templates ---
131	const memoryInitTemplatesSource = resolve(
132	  repoRoot,
133	  ".opencode/skills/atoms/corgispec-memory-init/templates"
134	);
135	const memoryInitTemplatesDest = resolve(assetsDir, "memory-init/templates");
136	
137	if (existsSync(memoryInitTemplatesSource)) {
138	  mkdirSync(resolve(assetsDir, "memory-init"), { recursive: true });
139	  cpSync(memoryInitTemplatesSource, memoryInitTemplatesDest, { recursive: true });
140	  totalFiles++;
141	  console.log(`✓ Bundled corgispec-memory-init templates from ${memoryInitTemplatesSource}`);
142	} else {
143	  errors.push(`Memory init templates source not found at ${memoryInitTemplatesSource}`);
144	}
145	
146	// --- 4. Bundle JSON schemas (for skill validation) ---
147	const jsonSchemasSource = resolve(repoRoot, "schemas");
148	const schemasDest = resolve(assetsDir, "schemas");
149	mkdirSync(schemasDest, { recursive: true });
150	
151	if (existsSync(jsonSchemasSource)) {
152	  const schemaFiles = readdirSync(jsonSchemasSource).filter((f) => f.endsWith(".json"));
153	
154	  for (const file of schemaFiles) {
155	    cpSync(resolve(jsonSchemasSource, file), resolve(schemasDest, file));
156	    totalFiles++;
157	  }
158	
159	  console.log(`✓ Bundled ${schemaFiles.length} JSON schema(s) from ${jsonSchemasSource}`);
160	} else {
161	  errors.push(`JSON schemas source not found at ${jsonSchemasSource}`);
162	}
163	
164	// --- 5. Bundle workflow schemas (for init/doctor) ---
165	const workflowSchemasSource = resolve(repoRoot, "openspec/schemas");
166	
167	if (existsSync(workflowSchemasSource)) {
168	  const entries = readdirSync(workflowSchemasSource, { withFileTypes: true });
169	  let workflowCount = 0;
170	
171	  for (const entry of entries) {
172	    if (entry.isDirectory()) {
173	      const src = resolve(workflowSchemasSource, entry.name);
174	      const dest = resolve(schemasDest, entry.name);
175	      cpSync(src, dest, { recursive: true });
176	      workflowCount++;
177	
178	      // Validate: schema.yaml must exist in each workflow schema
179	      if (!existsSync(resolve(dest, "schema.yaml"))) {
180	        errors.push(`Workflow schema ${entry.name}: missing schema.yaml`);
181	      }
182	    }
183	  }
184	
185	  totalFiles += workflowCount;
186	  console.log(`✓ Bundled ${workflowCount} workflow schema(s) from ${workflowSchemasSource}`);
187	} else {
188	  errors.push(`Workflow schemas source not found at ${workflowSchemasSource}`);
189	}
190	
191	// --- 6. Content verification (checksum comparison) ---
192	console.log("\nVerifying bundled content...");
193	let verifyCount = 0;
194	let verifyErrors = 0;
195	
196	function verifyFile(srcPath, destPath) {
197	  if (!existsSync(srcPath) || !existsSync(destPath)) {
198	    return false;
199	  }
200	  const srcHash = createHash("sha256").update(readFileSync(srcPath)).digest("hex");
201	  const destHash = createHash("sha256").update(readFileSync(destPath)).digest("hex");
202	  return srcHash === destHash;
203	}
204	
205	// Verify skills
206	if (existsSync(skillsSource)) {
207	  function verifySkillEntries(parentDir, tier) {
208	    if (!existsSync(parentDir)) return;
209	    const entries = readdirSync(parentDir, { withFileTypes: true });
210	    for (const entry of entries) {
211	      if (entry.isDirectory() && entry.name.startsWith("corgispec-")) {
212	        for (const file of ["SKILL.md", "skill.meta.json"]) {
213	          const src = resolve(parentDir, entry.name, file);
214	          const destParent = tier ? resolve(skillsDest, tier) : skillsDest;
215	          const dest = resolve(destParent, entry.name, file);
216	          if (existsSync(src)) {
217	            if (verifyFile(src, dest)) {
218	              verifyCount++;
219	            } else {
220	              verifyErrors++;
221	              errors.push(`Checksum mismatch: ${entry.name}/${file}`);
222	            }
223	          }
224	        }
225	      }
226	    }
227	  }
228	
229	  for (const tier of tierDirs) {
230	    verifySkillEntries(resolve(skillsSource, tier), tier);
231	  }
232	  verifySkillEntries(skillsSource, null);
233	}
234	
235	// Verify JSON schemas
236	if (existsSync(jsonSchemasSource)) {
237	  for (const file of readdirSync(jsonSchemasSource).filter((f) => f.endsWith(".json"))) {
238	    if (verifyFile(resolve(jsonSchemasSource, file), resolve(schemasDest, file))) {
239	      verifyCount++;
240	    } else {
241	      verifyErrors++;
242	      errors.push(`Checksum mismatch: schemas/${file}`);
243	    }
244	  }
245	}
246	
247	// Verify representative command and memory-init assets
248	for (const [label, src, dest] of [
249	  [
250	    "commands/opencode/corgi-install.md",
251	    resolve(opencodeCommandsSource, "corgi-install.md"),
252	    resolve(opencodeCommandsDest, "corgi-install.md"),
253	  ],
254	  [
255	    "commands/claude/corgi/install.md",
256	    resolve(claudeCommandsSource, "install.md"),
257	    resolve(claudeCommandsDest, "install.md"),
258	  ],
259	  [
260	    "memory-init/templates/session-memory-protocol.md",
261	    resolve(memoryInitTemplatesSource, "session-memory-protocol.md"),
262	    resolve(memoryInitTemplatesDest, "session-memory-protocol.md"),
263	  ],
264	]) {
265	  if (verifyFile(src, dest)) {
266	    verifyCount++;
267	  } else {
268	    verifyErrors++;
269	    errors.push(`Checksum mismatch: ${label}`);
270	  }
271	}
272	
273	console.log(`✓ Verified ${verifyCount} file(s), ${verifyErrors} mismatch(es)`);
274	
275	// --- Summary ---
276	console.log(`\nAssets bundled to ${assetsDir}`);
277	console.log(`Total: ${totalFiles} items bundled`);
278	
279	if (errors.length > 0) {
280	  console.error("\nErrors:");
281	  for (const e of errors) {
282	    console.error(`  ✗ ${e}`);
283	  }
284	  process.exit(1);
285	}
