112	/**
113	 * Generate instruction JSON for the apply phase (next task group).
114	 */
115	export function resolveApplyInstruction(
116	  cwd: string,
117	  changeName: string
118	): ApplyInstruction {
119	  const schema = loadWorkflowSchema(cwd);
120	  const config = loadConfigFromDir(cwd);
121	  const changeInfo = getChangeInfo(cwd, changeName);
122	  const changeDir = resolve(cwd, "openspec/changes", changeName);
123	
124	  const currentGroup = findNextTaskGroup(changeInfo.taskGroups);
125	
126	  // Build context files list
127	  const contextFiles: string[] = [];
128	
129	  // Always include tasks.md
130	  const tasksPath = resolve(changeDir, "tasks.md");
131	  if (existsSync(tasksPath)) contextFiles.push(tasksPath);
132	
133	  // Include design.md if exists
134	  const designPath = resolve(changeDir, "design.md");
135	  if (existsSync(designPath)) contextFiles.push(designPath);
136	
137	  // Include spec files
138	  const specsDir = resolve(changeDir, "specs");
139	  if (existsSync(specsDir)) {
140	    addMarkdownFilesFromDir(specsDir, contextFiles);
141	  }
142	
143	  // Include proposal
144	  const proposalPath = resolve(changeDir, "proposal.md");
145	  if (existsSync(proposalPath)) contextFiles.push(proposalPath);
146	
147	  return {
148	    changeName,
149	    state: changeInfo.state,
150	    currentGroup,
151	    instruction: schema.apply.instruction,
152	    contextFiles,
153	    projectContext: config.context ?? "",
154	  };
155	}
