208	/**
209	 * Generate instruction JSON for the archive phase.
210	 */
211	export function resolveArchiveInstruction(
212	  cwd: string,
213	  changeName: string
214	): ArchiveInstruction {
215	  const changeInfo = getChangeInfo(cwd, changeName);
216	  const changeDir = resolve(cwd, "openspec/changes", changeName);
217	
218	  const isReady = changeInfo.isComplete;
219	  let reason: string | undefined;
220	
221	  if (!isReady) {
222	    const remaining = changeInfo.totalTasks - changeInfo.completedTasks;
223	    reason = `Change not ready for archive: ${remaining} tasks remaining`;
224	  }
225	
226	  // Context files
227	  const contextFiles: string[] = [];
228	  const specsDir = resolve(changeDir, "specs");
229	  if (existsSync(specsDir)) addMarkdownFilesFromDir(specsDir, contextFiles);
230	  const proposalPath = resolve(changeDir, "proposal.md");
231	  if (existsSync(proposalPath)) contextFiles.push(proposalPath);
232	
233	  const instruction = isReady
234	    ? `Archive the completed change:
235	1. Merge delta specs from specs/ into the main openspec/specs/ directory
236	2. Move the change directory to openspec/archive/${changeName}/
237	3. Close any associated issues
238	4. Update any references to this change`
239	    : reason!;
240	
241	  return {
242	    changeName,
243	    state: changeInfo.state,
244	    isReady,
245	    reason,
246	    instruction,
247	    contextFiles,
248	  };
249	}
250	
251	// ─── Helpers ────────────────────────────────────────────────────────────
252	
253	function gatherContextFiles(
254	  changeDir: string,
255	  requires: string[],
256	  schema: { artifacts: SchemaArtifact[] }
257	): string[] {
258	  const files: string[] = [];
259	
260	  for (const depId of requires) {
261	    const depArtifact = schema.artifacts.find((a) => a.id === depId);
262	    if (!depArtifact) continue;
263	
264	    const generates = depArtifact.generates;
265	    if (generates.includes("*")) {
266	      // Spec files — add all from the directory
267	      const baseDir = generates.split("/")[0]!;
268	      const dir = resolve(changeDir, baseDir);
269	      if (existsSync(dir)) {
270	        addMarkdownFilesFromDir(dir, files);
271	      }
272	    } else {
273	      const filePath = resolve(changeDir, generates);
274	      if (existsSync(filePath)) {
275	        files.push(filePath);
276	      }
277	    }
278	  }
279	
280	  return files;
281	}
282	
283	function addMarkdownFilesFromDir(dir: string, files: string[]): void {
284	  const entries = readdirSync(dir, { withFileTypes: true });
285	  for (const entry of entries) {
286	    const full = resolve(dir, entry.name);
287	    if (entry.isFile() && entry.name.endsWith(".md")) {
288	      files.push(full);
289	    } else if (entry.isDirectory()) {
290	      addMarkdownFilesFromDir(full, files);
291	    }
292	  }
293	}
294	
295	function getArtifactRules(
296	  config: OpenSpecConfig,
297	  artifactId: string
298	): string[] {
299	  if (!config.rules) return [];
300	  const rules = config.rules[artifactId];
301	  if (!rules) return [];
302	  return Array.isArray(rules) ? rules : [];
303	}
