88	function listFiles(rootDir: string): string[] {
89	  if (!existsSync(rootDir)) {
90	    return [];
91	  }
92	
93	  const files: string[] = [];
94	  for (const entry of readdirSync(rootDir, { withFileTypes: true })) {
95	    const fullPath = resolve(rootDir, entry.name);
96	    if (entry.isDirectory()) {
97	      files.push(...listFiles(fullPath));
98	      continue;
99	    }
100	    if (entry.isFile() || statSync(fullPath).isFile()) {
101	      files.push(fullPath);
