129	function readSchemaFromConfig(configPath: string): SchemaType | undefined {
130	  if (!existsSync(configPath)) {
131	    return undefined;
132	  }
133	
134	  const parsed = yaml.load(readFileSync(configPath, "utf-8"));
135	  if (!parsed || typeof parsed !== "object") {
136	    return undefined;
137	  }
138	
139	  const schema = (parsed as Record<string, unknown>).schema;
140	  if (schema === "github-tracked" || schema === "gitlab-tracked") {
141	    return schema;
142	  }
143	
144	  return undefined;
145	}
146	
147	function getManifestManagedFiles(manifestPath: string): string[] {
148	  const parsed = parseMaybeYamlOrJson(manifestPath) as InstallManifest | null;
149	  if (!parsed || typeof parsed !== "object") {
150	    return [];
151	  }
152	
153	  const managedFiles = new Set<string>();
154	
155	  for (const entry of parsed.managedFiles ?? []) {
156	    if (typeof entry === "string") {
157	      managedFiles.add(normalizeRelativePath(entry));
158	      continue;
159	    }
160	
161	    if (entry && typeof entry === "object" && typeof entry.path === "string") {
162	      managedFiles.add(normalizeRelativePath(entry.path));
163	    }
164	  }
165	
166	  for (const key of Object.keys(parsed.files ?? {})) {
167	    managedFiles.add(normalizeRelativePath(key));
168	  }
169	
170	  return Array.from(managedFiles).sort();
171	}
172	
173	function findLegacyManagedFiles(targetDir: string, schema?: SchemaType): string[] {
174	  const candidates = new Set<string>(LEGACY_MARKERS);
175	  if (schema) {
176	    candidates.add(`openspec/schemas/${schema}/schema.yaml`);
177	  }
178	
179	  return Array.from(candidates)
180	    .filter((relativePath) => existsSync(resolve(targetDir, relativePath)))
181	    .sort();
182	}
183	
184	export function classifyTargetState(targetDir: string): TargetState {
185	  const configPath = resolve(targetDir, "openspec/config.yaml");
186	  const hasConfig = existsSync(configPath);
187	  const manifestPath = getManifestPath(targetDir);
188	  const hasManifest = Boolean(manifestPath);
189	  const schema = readSchemaFromConfig(configPath);
190	  const manifestManagedFiles = manifestPath ? getManifestManagedFiles(manifestPath) : [];
191	  const managedFiles = findLegacyManagedFiles(targetDir, schema);
192	
193	  if (hasConfig && manifestPath && manifestManagedFiles.length > 0) {
194	    return {
195	      kind: "managed-update",
196	      hasConfig,
197	      hasManifest,
198	      configPath,
199	      manifestPath,
200	      managedFiles: manifestManagedFiles,
201	    };
202	  }
203	
204	  if (hasManifest) {
205	    return {
206	      kind: "inconsistent",
207	      hasConfig,
208	      hasManifest,
209	      configPath,
210	      manifestPath,
211	      managedFiles: manifestManagedFiles,
212	    };
213	  }
214	
215	  if (hasConfig && managedFiles.length > 0) {
216	    return {
217	      kind: "legacy",
218	      hasConfig,
219	      hasManifest,
220	      configPath,
221	      managedFiles,
222	    };
223	  }
224	
225	  if (managedFiles.length > 0) {
226	    return {
227	      kind: "inconsistent",
228	      hasConfig,
229	      hasManifest,
230	      configPath,
231	      managedFiles,
232	    };
233	  }
234	
235	  return {
236	    kind: hasConfig ? "fresh" : "init-needed",
237	    hasConfig,
238	    hasManifest,
239	    configPath,
240	    managedFiles: [],
241	  };
242	}
243	
244	export function getManagedProjectFiles(
245	  schema: SchemaType,
246	  assetsRoot?: string
247	): string[] {
248	  const root = getAssetsRoot(assetsRoot);
249	  return [
250	    ...listFiles(resolve(root, "commands/opencode")),
251	    ...listFiles(resolve(root, "commands/claude/corgi")),
252	    ...listFiles(resolve(root, "schemas", schema)),
253	  ].sort();
254	}
