191	        tasks: [],
192	        totalTasks: 0,
193	        completedTasks: 0,
194	        status: "pending",
195	      };
196	      continue;
197	    }
198	
199	    // Match task items: - [ ] or - [x]
200	    if (currentGroup) {
201	      const taskMatch = line.match(/^\s*- \[([ x])\]\s+([\d.]+)\s+(.*)/);
202	      if (taskMatch) {
203	        const done = taskMatch[1] === "x";
204	        currentGroup.tasks.push({
205	          id: taskMatch[2]!,
206	          description: taskMatch[3]!.trim(),
207	          done,
208	        });
209	      }
210	    }
211	  }
212	
213	  if (currentGroup) {
214	    finalizeGroup(currentGroup);
215	    groups.push(currentGroup);
216	  }
217	
218	  return groups;
219	}
220	
221	function finalizeGroup(group: TaskGroup): void {
222	  group.totalTasks = group.tasks.length;
223	  group.completedTasks = group.tasks.filter((t) => t.done).length;
224	
225	  if (group.completedTasks === group.totalTasks && group.totalTasks > 0) {
226	    group.status = "done";
227	  } else if (group.completedTasks > 0) {
228	    group.status = "in_progress";
229	  } else {
230	    group.status = "pending";
231	  }
232	}
233	
234	// ─── Change Status ──────────────────────────────────────────────────────
235	
236	/**
237	 * Get full status information for a specific change.
238	 */
239	export function getChangeInfo(cwd: string, changeName: string): ChangeInfo {
240	  const changeDir = resolve(cwd, "openspec/changes", changeName);
241	  if (!existsSync(changeDir)) {
242	    throw new Error(`Change '${changeName}' not found at ${changeDir}`);
243	  }
244	
245	  const schema = loadWorkflowSchema(cwd);
246	
247	  // Determine artifact statuses
248	  const artifactStatuses: ArtifactStatus[] = [];
249	  const completedArtifacts = new Set<string>();
250	
251	  for (const artifact of schema.artifacts) {
252	    const exists = artifactExists(changeDir, artifact.generates);
253	    if (exists) completedArtifacts.add(artifact.id);
254	  }
255	
256	  for (const artifact of schema.artifacts) {
257	    const exists = completedArtifacts.has(artifact.id);
258	    const blockedBy = artifact.requires.filter(
259	      (dep) => !completedArtifacts.has(dep)
260	    );
261	    const blocked = blockedBy.length > 0;
262	    const ready = !exists && !blocked;
263	
264	    artifactStatuses.push({
265	      id: artifact.id,
266	      description: artifact.description,
267	      generates: artifact.generates,
268	      exists,
269	      ready,
270	      blocked,
271	      blockedBy,
272	    });
273	  }
274	
275	  // Parse task groups
276	  const tasksPath = resolve(changeDir, "tasks.md");
277	  let taskGroups: TaskGroup[] = [];
278	  let completedTasks = 0;
279	  let totalTasks = 0;
280	
281	  if (existsSync(tasksPath)) {
282	    const content = readFileSync(tasksPath, "utf-8");
283	    taskGroups = parseTaskGroups(content);
284	    for (const g of taskGroups) {
285	      completedTasks += g.completedTasks;
286	      totalTasks += g.totalTasks;
287	    }
288	  }
289	
290	  // Determine state
291	  const state = determineState(artifactStatuses, taskGroups, completedArtifacts);
292	
293	  // Last modified
294	  const stat = statSync(changeDir);
295	
296	  return {
297	    name: changeName,
298	    directory: changeDir,
299	    state,
300	    schemaName: schema.name,
301	    artifacts: artifactStatuses,
302	    taskGroups,
303	    completedTasks,
304	    totalTasks,
305	    isComplete: totalTasks > 0 && completedTasks === totalTasks,
306	    lastModified: stat.mtime.toISOString(),
307	  };
308	}
309	
310	function determineState(
311	  artifacts: ArtifactStatus[],
312	  taskGroups: TaskGroup[],
313	  completedArtifacts: Set<string>
314	): ChangeState {
315	  // If no artifacts exist at all
316	  if (completedArtifacts.size === 0) return "empty";
317	
318	  // If tasks exist and all done
319	  if (
320	    completedArtifacts.has("tasks") &&
321	    taskGroups.length > 0 &&
322	    taskGroups.every((g) => g.status === "done")
323	  ) {
324	    return "all_done";
325	  }
326	
327	  // If tasks exist, we're in apply phase
328	  if (completedArtifacts.has("tasks")) return "applying";
329	
330	  // Check which artifact we're working on
331	  if (!completedArtifacts.has("proposal")) return "proposing";
332	  if (!completedArtifacts.has("specs")) return "specifying";
333	  if (!completedArtifacts.has("design")) return "designing";
334	  if (!completedArtifacts.has("tasks")) return "tasking";
335	
336	  return "applying";
337	}
338	
339	/**
340	 * Find the next task group to work on (first with pending tasks).
341	 */
342	export function findNextTaskGroup(taskGroups: TaskGroup[]): TaskGroup | null {
343	  return taskGroups.find((g) => g.status !== "done") ?? null;
344	}
