1	import { readFileSync, existsSync, readdirSync } from "node:fs";
2	import { resolve, basename } from "node:path";
3	import { createSchemaRegistry, type ValidationResult } from "./schemas.js";
4	
5	/**
6	 * Skill tiers in hierarchy order.
7	 */
8	export type SkillTier = "atom" | "molecule" | "compound";
9	
10	/**
11	 * Platform scope for a skill.
12	 */
13	export type SkillPlatform = "universal" | "github" | "gitlab";
14	
15	/**
16	 * Installation target platforms.
17	 */
18	export type InstallTarget = "opencode" | "claude" | "codex";
19	
20	/**
21	 * Parsed skill metadata from skill.meta.json.
22	 */
23	export interface SkillMeta {
24	  slug: string;
25	  tier: SkillTier;
26	  version: string;
27	  description: string;
28	  depends_on: string[];
29	  platform: SkillPlatform;
30	  tags?: string[];
31	  installation: {
32	    targets: InstallTarget[];
33	    base_path: string;
34	  };
35	}
36	
37	/**
38	 * A discovered skill with its directory path and parsed metadata.
39	 */
40	export interface DiscoveredSkill {
41	  slug: string;
42	  dir: string;
43	  meta: SkillMeta;
44	  hasSkillMd: boolean;
45	}
46	
47	/**
48	 * Validation issue for a single skill.
49	 */
50	export interface SkillValidationIssue {
51	  slug: string;
52	  dir: string;
53	  issues: string[];
54	}
55	
56	/**
57	 * Discover all skills in a directory.
58	 * Skills are directories containing skill.meta.json.
59	 * Supports tiered layout (atoms/, molecules/, compounds/) with flat-root fallback.
60	 */
61	export function discoverSkills(skillsDir: string): DiscoveredSkill[] {
62	  if (!existsSync(skillsDir)) {
63	    return [];
64	  }
65	
66	  const tierDirs = ["atoms", "molecules", "compounds"];
67	  const skills: DiscoveredSkill[] = [];
68	
69	  function loadEntry(dir: string, name: string): void {
70	    const skillDir = resolve(dir, name);
71	    const metaPath = resolve(skillDir, "skill.meta.json");
72	
73	    if (!existsSync(metaPath)) return;
74	
75	    try {
76	      const metaContent = readFileSync(metaPath, "utf-8");
77	      const meta = JSON.parse(metaContent) as SkillMeta;
78	      const hasSkillMd = existsSync(resolve(skillDir, "SKILL.md"));
79	
80	      skills.push({ slug: name, dir: skillDir, meta, hasSkillMd });
81	    } catch {
82	      skills.push({
83	        slug: name,
84	        dir: skillDir,
85	        meta: {
86	          slug: name,
87	          tier: "atom",
88	          version: "0.0.0",
89	          description: "(parse error)",
90	          depends_on: [],
91	          platform: "universal",
92	          installation: { targets: [], base_path: "" },
93	        },
94	        hasSkillMd: existsSync(resolve(skillDir, "SKILL.md")),
95	      });
96	    }
97	  }
98	
99	  // Phase 1: scan tier subdirectories
100	  for (const tier of tierDirs) {
101	    const tierPath = resolve(skillsDir, tier);
102	    if (!existsSync(tierPath)) continue;
103	    try {
104	      const entries = readdirSync(tierPath, { withFileTypes: true });
105	      for (const entry of entries) {
106	        if (entry.isDirectory()) loadEntry(tierPath, entry.name);
107	      }
108	    } catch {
109	      // tier dir unreadable, skip
110	    }
111	  }
112	
113	  // Phase 2: scan root for flat skills (backward compat)
114	  try {
115	    const entries = readdirSync(skillsDir, { withFileTypes: true });
116	    for (const entry of entries) {
117	      if (!entry.isDirectory()) continue;
118	      if (tierDirs.includes(entry.name)) continue;
119	      loadEntry(skillsDir, entry.name);
120	    }
121	  } catch {
122	    // root unreadable, skip
123	  }
124	
125	  return skills;
126	}
127	
128	/**
129	 * Discover skills from the default locations in a repo.
130	 * Searches: .opencode/skills/, .claude/skills/, .codex/skills/
131	 */
132	export function discoverSkillsFromRepo(repoRoot: string): DiscoveredSkill[] {
133	  const searchPaths = [
134	    resolve(repoRoot, ".opencode/skills"),
135	    resolve(repoRoot, ".claude/skills"),
136	    resolve(repoRoot, ".codex/skills"),
137	  ];
138	
139	  // Use the first one that has skills (canonical is .opencode/skills)
140	  for (const searchPath of searchPaths) {
141	    const skills = discoverSkills(searchPath);
142	    if (skills.length > 0) {
143	      return skills;
144	    }
145	  }
146	
147	  return [];
148	}
149	
150	/**
151	 * Validate a single skill against all constraints.
152	 * Returns a list of issues (empty = valid).
153	 */
154	export function validateSkill(
155	  skill: DiscoveredSkill,
156	  allSlugs: Set<string>,
157	  schemasDir?: string
158	): string[] {
159	  const issues: string[] = [];
160	
161	  // 1. SKILL.md exists
162	  if (!skill.hasSkillMd) {
163	    issues.push("Missing SKILL.md");
164	  }
165	
166	  // 2. Slug matches directory name
167	  if (skill.meta.slug !== skill.slug) {
168	    issues.push(
169	      `Slug mismatch: directory '${skill.slug}' vs meta '${skill.meta.slug}'`
170	    );
171	  }
172	
173	  // 3. Validate meta against JSON Schema
174	  try {
175	    const registry = createSchemaRegistry(schemasDir);
176	    const result: ValidationResult = registry.validate(
177	      "skill-meta.schema.json",
178	      skill.meta
179	    );
180	    if (!result.valid && result.errors) {
181	      for (const err of result.errors) {
182	        issues.push(`Schema: ${err.instancePath || "/"} ${err.message}`);
183	      }
184	    }
185	  } catch (err) {
186	    issues.push(
187	      `Schema validation failed: ${err instanceof Error ? err.message : String(err)}`
188	    );
189	  }
190	
191	  // 4. Tier constraints
192	  if (skill.meta.tier === "atom" && skill.meta.depends_on.length > 0) {
193	    issues.push("Atom skills must not have dependencies");
194	  }
195	
196	  // 5. Dependencies exist
197	  for (const dep of skill.meta.depends_on) {
198	    if (!allSlugs.has(dep)) {
199	      issues.push(`Dependency '${dep}' not found`);
200	    }
201	  }
202	
203	  // 6. Tier hierarchy: molecules only depend on atoms, compounds on anything
204	  if (skill.meta.tier === "molecule") {
205	    // Would need to look up dep tiers — simplified check: just ensure deps exist
206	    // Full tier validation requires the full skill map
207	  }
208	
209	  return issues;
210	}
211	
212	/**
213	 * Validate all skills in a directory.
214	 */
215	export function validateAllSkills(
216	  skillsDir: string,
217	  schemasDir?: string
218	): SkillValidationIssue[] {
219	  const skills = discoverSkills(skillsDir);
220	  const allSlugs = new Set(skills.map((s) => s.slug));
221	  const results: SkillValidationIssue[] = [];
222	
223	  for (const skill of skills) {
224	    const issues = validateSkill(skill, allSlugs, schemasDir);
225	    if (issues.length > 0) {
226	      results.push({ slug: skill.slug, dir: skill.dir, issues });
227	    }
228	  }
229	
230	  return results;
231	}
232	
233	/**
234	 * Filter skills by tier and/or platform.
235	 */
236	export function filterSkills(
237	  skills: DiscoveredSkill[],
238	  options: { tier?: SkillTier; platform?: SkillPlatform }
239	): DiscoveredSkill[] {
240	  let filtered = skills;
241	
242	  if (options.tier) {
243	    filtered = filtered.filter((s) => s.meta.tier === options.tier);
244	  }
245	
246	  if (options.platform) {
247	    filtered = filtered.filter((s) => s.meta.platform === options.platform);
248	  }
249	
250	  return filtered;
251	}
