28	/**
29	 * Install skills to a target directory.
30	 * Source may be tiered (atoms/, molecules/, compounds/) or flat.
31	 * Target is always flat (agent platforms expect flat user-level layout).
32	 */
33	export function installSkillsTo(
34	  sourceDir: string,
35	  targetDir: string,
36	  dryRun: boolean
37	): string[] {
38	  const installed: string[] = [];
39	  const tierDirs = ["atoms", "molecules", "compounds"];
40	
41	  if (!existsSync(sourceDir)) {
42	    return installed;
43	  }
44	
45	  function installEntry(src: string, name: string): void {
46	    const dest = resolve(targetDir, name);
47	    if (dryRun) {
48	      console.log(`  DRY-RUN: ${src} → ${dest}`);
49	    } else {
50	      mkdirSync(targetDir, { recursive: true });
51	      if (existsSync(dest)) {
52	        rmSync(dest, { recursive: true });
53	      }
54	      cpSync(src, dest, { recursive: true });
55	      console.log(`  Installed: ${name} → ${dest}`);
56	    }
57	    installed.push(name);
58	  }
59	
60	  // Scan tier subdirectories
61	  for (const tier of tierDirs) {
62	    const tierPath = resolve(sourceDir, tier);
63	    if (!existsSync(tierPath)) continue;
64	    const entries = readdirSync(tierPath, { withFileTypes: true });
65	    for (const entry of entries) {
66	      if (!entry.isDirectory()) continue;
67	      installEntry(resolve(tierPath, entry.name), entry.name);
68	    }
69	  }
70	
71	  // Scan root for flat skills (backward compat)
72	  const entries = readdirSync(sourceDir, { withFileTypes: true });
73	  for (const entry of entries) {
74	    if (!entry.isDirectory()) continue;
75	    if (tierDirs.includes(entry.name)) continue;
76	    installEntry(resolve(sourceDir, entry.name), entry.name);
77	  }
78	
79	  return installed;
80	}
81	
82	export function createInstallCommand(): Command {
83	  const cmd = new Command("install");
84	
85	  cmd
86	    .description("Install bundled skills to user-level platform directories")
87	    .option(
88	      "--platform <platform>",
89	      "Install to specific platform only (claude, opencode, codex)"
90	    )
91	    .option("--dry-run", "Print planned operations without copying files")
92	    .action((opts) => {
93	      const dryRun = opts.dryRun ?? false;
94	      const platformFilter: Platform | undefined = opts.platform;
95	
96	      if (
97	        platformFilter &&
98	        !["claude", "opencode", "codex"].includes(platformFilter)
99	      ) {
100	        console.error(
101	          `Error: Invalid platform '${platformFilter}'. Choose: claude, opencode, codex`
102	        );
103	        process.exit(1);
104	      }
105	
106	      let sourceDir: string;
107	      try {
108	        sourceDir = getBundledSkillsDir();
109	      } catch (err) {
110	        console.error(
111	          err instanceof Error ? err.message : "Failed to locate bundled skills"
112	        );
113	        process.exit(1);
114	      }
115	
116	      const platforms: Platform[] = platformFilter
117	        ? [platformFilter]
118	        : ["claude", "opencode", "codex"];
119	
120	      if (dryRun) {
121	        console.log("DRY RUN — no files will be written\n");
122	      }
123	
124	      let totalInstalled = 0;
125	
126	      for (const platform of platforms) {
127	        const targetDir = getSkillDir(platform);
128	        console.log(`\n${platform}: ${targetDir}`);
129	
130	        const installed = installSkillsTo(sourceDir, targetDir, dryRun);
131	        totalInstalled += installed.length;
132	
133	        if (installed.length === 0) {
134	          console.log("  (no skills to install)");
135	        }
136	      }
137	
138	      console.log(
139	        `\n${dryRun ? "Would install" : "Installed"} ${totalInstalled} skill(s) across ${platforms.length} platform(s).`
140	      );
141	
142	      if (!dryRun && totalInstalled > 0) {
143	        console.log(
144	          "\n💡 Tip: Run `corgispec hooks generate` to enable auto context injection & security guards."
145	        );
146	      }
147	    });
148	
149	  return cmd;
150	}
