5	/**
6	 * Supported AI coding platforms.
7	 */
8	export type Platform = "claude" | "opencode" | "codex";
9	
10	/**
11	 * Platform detection result.
12	 */
13	export interface PlatformInfo {
14	  platform: Platform;
15	  detected: boolean;
16	  skillDir: string;
17	  exists: boolean;
18	  writable?: boolean;
19	}
