8	
9	const __dirname = dirname(fileURLToPath(import.meta.url));
10	const VALID_SCHEMAS = ["github-tracked", "gitlab-tracked"] as const;
11	const VALID_MODES = ["auto", "fresh", "update", "legacy", "verify"] as const;
12	type ValidationResult<T> = { ok: true; value: T } | { ok: false };
13	
14	interface BootstrapCommandOptions {
15	  target?: string;
16	  schema?: SchemaType;
17	  mode?: BootstrapMode;
18	  yes?: boolean;
19	  memory?: boolean;
20	  json?: boolean;
21	}
22	
23	export function createBootstrapCommand(): Command {
24	  const cmd = new Command("bootstrap");
25	
26	  cmd
27	    .description("Bootstrap Corgi assets and user-level skills into a project")
28	    .option("--target <path>", "Target project directory", ".")
29	    .option("--schema <schema>", "Schema to use (github-tracked or gitlab-tracked)")
30	    .option("--mode <mode>", "Bootstrap mode (auto, fresh, update, legacy, verify)", "auto")
31	    .option("--yes", "Approve destructive legacy migration steps")
32	    .option("--no-memory", "Skip initializing project memory files")
33	    .option("--json", "Output bootstrap result as JSON")
34	    .action(async (opts: BootstrapCommandOptions) => {
35	      const schema = validateSchema(opts.schema);
36	      const mode = validateMode(opts.mode);
37	
38	      if (!schema.ok || !mode.ok) {
39	        process.exitCode = 1;
40	        return;
41	      }
42	
43	      const result = await runBootstrap({
44	        target: opts.target ?? ".",
45	        schema: schema.value,
46	        mode: mode.value,
47	        yes: opts.yes ?? false,
48	        noMemory: opts.memory === false,
49	        json: opts.json ?? false,
50	        assetsRoot: resolveBootstrapAssetsRoot(),
51	      });
52	
53	      if (opts.json) {
54	        console.log(JSON.stringify(result, null, 2));
55	      } else {
56	        printBootstrapSummary(result);
57	      }
58	
59	      if (result.status !== "success") {
60	        process.exitCode = 1;
61	      }
62	    });
63	
64	  return cmd;
65	}
66	
67	function resolveBootstrapAssetsRoot(): string {
68	  const candidates = [
69	    resolve(__dirname, "../assets"),
70	    resolve(__dirname, "../../assets"),
71	  ];
72	
73	  for (const candidate of candidates) {
74	    if (existsSync(resolve(candidate, "commands"))) {
75	      return candidate;
76	    }
77	  }
78	
79	  return candidates[0]!;
80	}
81	
82	function validateSchema(schema: string | undefined): ValidationResult<SchemaType | undefined> {
83	  if (schema === undefined) {
84	    return { ok: true, value: undefined };
85	  }
86	
87	  if ((VALID_SCHEMAS as readonly string[]).includes(schema)) {
88	    return { ok: true, value: schema as SchemaType };
89	  }
90	
91	  console.log(
92	    `Invalid schema '${schema}'. Supported: ${VALID_SCHEMAS.join(", ")}`
93	  );
94	  return { ok: false };
95	}
96	
97	function validateMode(mode: string | undefined): ValidationResult<BootstrapMode> {
98	  const candidate = mode ?? "auto";
99	
100	  if ((VALID_MODES as readonly string[]).includes(candidate)) {
101	    return { ok: true, value: candidate as BootstrapMode };
102	  }
103	
104	  console.log(`Invalid mode '${candidate}'. Supported: ${VALID_MODES.join(", ")}`);
105	  return { ok: false };
106	}
107	
108	function printBootstrapSummary(result: Awaited<ReturnType<typeof runBootstrap>>): void {
109	  console.log(`Status: ${result.status}`);
110	  console.log(`Mode: ${result.mode}`);
111	  console.log(`Message: ${result.message}`);
112	  console.log(`Report: ${result.reportPath}`);
113	
114	  if (result.actions.length > 0) {
115	    console.log("Actions:");
116	    for (const action of result.actions) {
117	      console.log(`- ${action}`);
118	    }
119	  }
120	}
