167	  mkdirSync(resolve(openspecDir, "changes"), { recursive: true });
168	  mkdirSync(resolve(openspecDir, "schemas"), { recursive: true });
169	  mkdirSync(resolve(openspecDir, "specs"), { recursive: true });
170	
171	  const configContent = CONFIG_TEMPLATE.replace("{{schema}}", options.schema);
172	  writeFileSync(configPath, configContent);
