174	  if (!options.bundledSchemasDir) {
175	    return;
176	  }
177	
178	  const sourceSchema = resolve(options.bundledSchemasDir, options.schema);
179	  const targetSchema = resolve(openspecDir, "schemas", options.schema);
180	  if (existsSync(sourceSchema) && !existsSync(targetSchema)) {
181	    cpSync(sourceSchema, targetSchema, { recursive: true });
