220	function runPrerequisiteChecks(context: BootstrapContext, target: string, schema: SchemaType): void {
221	  ensureProjectAssets(context.assetsRoot, context);
222	
223	  if (!existsSync(target)) {
224	    throw new Error(`Target directory does not exist: ${target}`);
225	  }
226	
227	  context.checks.push({
228	    name: "openspec CLI",
229	    status: "PASS",
230	    detail: `runBootstrap available for ${basename(target) || target}`,
231	  });
232	
233	  const cliRequirement = schema === "gitlab-tracked" ? "glab" : "gh";
234	  const cliStatus = checkCliAvailability(cliRequirement);
235	  if (!cliStatus.ok) {
236	    context.checks.push({
237	      name: "gh/glab CLI",
238	      status: "FAIL",
239	      detail: cliStatus.detail,
240	    });
241	    throw new Error(cliStatus.detail);
242	  }
243	
244	  context.checks.push({
245	    name: "gh/glab CLI",
