251	function ensureProjectAssets(assetsRoot: string, context: BootstrapContext): void {
252	  const missing: string[] = [];
253	  for (const relativeDir of REQUIRED_PROJECT_ASSET_DIRS) {
254	    const fullPath = resolve(assetsRoot, relativeDir);
255	    if (!existsSync(fullPath)) {
256	      missing.push(relativeDir);
257	    }
258	  }
259	
260	  if (missing.length > 0) {
261	    const detail = `Bootstrap assets missing: ${missing.join(", ")}`;
262	    context.checks.push({
263	      name: "Bundled assets",
264	      status: "FAIL",
265	      detail,
266	    });
267	    throw new Error(detail);
268	  }
269	
270	  const commandCount = readdirSync(resolve(assetsRoot, "commands/opencode"), {
271	    withFileTypes: true,
272	  }).filter((entry) => entry.isFile()).length;
273	
274	  if (commandCount === 0) {
275	    const detail = "Bootstrap assets are incomplete: no OpenCode command assets were bundled.";
276	    context.checks.push({
277	      name: "Bundled assets",
278	      status: "FAIL",
279	      detail,
280	    });
281	    throw new Error(detail);
282	  }
283	
284	  context.checks.push({
285	    name: "Bundled assets",
286	    status: "PASS",
287	    detail: `Verified bundled commands, schemas, skills, and memory templates under ${assetsRoot}`,
288	  });
289	}
