291	function checkCliAvailability(command: "gh" | "glab"): { ok: boolean; detail: string } {
292	  const version = spawnSync(command, ["--version"], {
293	    encoding: "utf-8",
294	  });
295	
296	  if (version.error || version.status !== 0) {
297	    return {
298	      ok: false,
299	      detail: `${command} CLI is required for this schema but is unavailable.`,
300	    };
301	  }
302	
303	  const authArgs = command === "gh" ? ["auth", "status"] : ["auth", "status"];
304	  const auth = spawnSync(command, authArgs, {
305	    encoding: "utf-8",
306	  });
307	
308	  if (auth.error || auth.status !== 0) {
309	    return {
310	      ok: false,
311	      detail: `${command} CLI is installed but not authenticated.`,
312	    };
313	  }
314	
315	  const versionLine = `${version.stdout}${version.stderr}`.split(/\r?\n/).find(Boolean) ?? `${command} available`;
316	  return {
317	    ok: true,
318	    detail: versionLine.trim(),
319	  };
320	}
