352	function syncManagedProjectFiles(
353	  target: string,
354	  schema: SchemaType,
355	  assetsRoot: string,
356	  context: BootstrapContext
357	): string[] {
358	  const sourceFiles = getManagedProjectFiles(schema, assetsRoot);
