384	function projectRelativePathFromAsset(assetsRoot: string, schema: SchemaType, sourceFile: string): string {
385	  const commandsOpencodeRoot = resolve(assetsRoot, "commands/opencode");
386	  const commandsClaudeRoot = resolve(assetsRoot, "commands/claude/corgi");
387	  const schemaRoot = resolve(assetsRoot, "schemas", schema);
388	
389	  if (sourceFile.startsWith(commandsOpencodeRoot)) {
390	    return `.opencode/commands/${relativeManagedFiles(commandsOpencodeRoot, [sourceFile])[0]}`;
391	  }
392	  if (sourceFile.startsWith(commandsClaudeRoot)) {
393	    return `.claude/commands/corgi/${relativeManagedFiles(commandsClaudeRoot, [sourceFile])[0]}`;
394	  }
395	  if (sourceFile.startsWith(schemaRoot)) {
396	    return `openspec/schemas/${schema}/${relativeManagedFiles(schemaRoot, [sourceFile])[0]}`;
397	  }
398	
399	  throw new Error(`Unsupported managed asset path: ${sourceFile}`);
400	}
