463	function detectSchema(target: string): SchemaType | undefined {
464	  const configPath = resolve(target, "openspec/config.yaml");
465	  if (!existsSync(configPath)) {
466	    return undefined;
467	  }
468	  const parsed = yaml.load(readFileSync(configPath, "utf-8")) as { schema?: unknown } | null;
469	  return parsed?.schema === "gitlab-tracked" || parsed?.schema === "github-tracked"
470	    ? parsed.schema
471	    : undefined;
