474	function resolveBootstrapMode(requested: BootstrapMode, targetState: ReturnType<typeof classifyTargetState>["kind"]): BootstrapResult["mode"] {
475	  if (requested === "fresh") return "fresh";
476	  if (requested === "update") return "update";
477	  if (requested === "legacy") return "legacy";
478	  if (requested === "verify") return "verify";
479	
480	  switch (targetState) {
481	    case "managed-update":
482	      return "update";
483	    case "legacy":
484	      return "legacy";
485	    default:
486	      return "fresh";
487	  }
488	}
489	
490	function getExplicitModeMismatch(
491	  requested: BootstrapMode,
492	  targetState: ReturnType<typeof classifyTargetState>["kind"]
493	): string | null {
494	  if (requested === "auto" || requested === "verify") {
495	    return null;
496	  }
497	
498	  const compatibleStates: Record<Exclude<BootstrapMode, "auto" | "verify">, Array<ReturnType<typeof classifyTargetState>["kind"]>> = {
499	    fresh: ["fresh", "init-needed"],
500	    update: ["managed-update"],
501	    legacy: ["legacy"],
502	  };
503	
504	  if (compatibleStates[requested].includes(targetState)) {
505	    return null;
506	  }
507	
508	  return `Explicit mode '${requested}' is incompatible with target state '${targetState}'.`;
509	}
510	
511	function finalize(
512	  context: BootstrapContext,
513	  target: string,
514	  status: BootstrapResult["status"],
515	  message: string
516	): BootstrapResult {
517	  const shouldWriteReport = existsSync(target);
518	  const reportPath = shouldWriteReport
519	    ? writeInstallReport({
520	        targetDir: target,
521	        sourceRepo: context.sourceRepo,
522	        mode: context.reportMode,
523	        timestamp: context.timestamp,
524	        checks: context.checks,
525	        actions: context.actions,
526	        overall: status === "success" ? "PASS" : "FAIL",
527	      })
528	    : resolve(target, "openspec/.corgi-install-report.md");
529	
530	  return {
531	    status,
532	    mode: context.resultMode,
533	    target,
534	    actions: context.actions,
535	    reportPath,
536	    manifestPath: context.manifestPath,
537	    message,
538	  };
539	}
