1	import { Command } from "commander";
2	import { resolve } from "node:path";
3	import { existsSync, accessSync, constants, readdirSync, readFileSync } from "node:fs";
4	import { homedir } from "node:os";
5	import { findConfigPath, loadConfig } from "../lib/config.js";
