10	interface CheckResult {
11	  name: string;
12	  passed: boolean;
13	  message: string;
14	  suggestion?: string;
15	}
16	
17	export function createDoctorCommand(): Command {
18	  const cmd = new Command("doctor");
19	
20	  cmd
21	    .description(
22	      "Diagnose runtime environment and report issues with suggestions"
23	    )
24	    .option("--path <dir>", "Working directory", ".")
25	    .option("--json", "Output as JSON")
26	    .action((opts) => {
27	      const cwd = resolve(opts.path);
28	      const results: CheckResult[] = [];
29	
30	      // 1. Node version check
31	      results.push(checkNodeVersion());
32	
33	      // 2. Skill directory checks
34	      results.push(...checkSkillDirs());
35	
36	      // 3. Config validation
37	      results.push(checkConfig(cwd));
38	
39	      // 4. Platform detection
40	      results.push(...checkPlatforms());
41	
42	      // 5. Hook configuration
43	      results.push(checkHooks(cwd));
44	
45	      // 6. Schema validation
46	      results.push(checkSchemas(cwd));
47	
48	      // Output
49	      if (opts.json) {
50	        console.log(JSON.stringify(results, null, 2));
51	      } else {
52	        printResults(results);
53	      }
54	
55	      // Exit code
56	      const hasFailure = results.some((r) => !r.passed);
57	      if (hasFailure) {
58	        process.exitCode = 1;
59	      }
60	    });
61	
62	  return cmd;
63	}
64	
65	function checkNodeVersion(): CheckResult {
66	  const version = process.versions.node;
67	  const major = parseInt(version.split(".")[0]!, 10);
68	
69	  if (major >= 18) {
70	    return {
71	      name: "Node.js",
72	      passed: true,
73	      message: `v${version}`,
74	    };
75	  }
76	
77	  return {
78	    name: "Node.js",
79	    passed: false,
80	    message: `v${version} (requires >= 18)`,
81	    suggestion: "Upgrade Node.js to version 18 or later.",
82	  };
83	}
84	
85	function checkSkillDirs(): CheckResult[] {
86	  const results: CheckResult[] = [];
87	  const home = homedir();
88	
89	  const dirs = [
90	    { name: "~/.claude/skills/", path: resolve(home, ".claude/skills") },
91	    {
92	      name: "~/.config/opencode/skill/",
93	      path: resolve(home, ".config/opencode/skill"),
94	    },
95	  ];
96	
97	  for (const dir of dirs) {
98	    if (!existsSync(dir.path)) {
99	      results.push({
100	        name: dir.name,
101	        passed: false,
102	        message: "not found",
103	        suggestion: `Run \`corgispec install\` to create.`,
104	      });
105	    } else {
106	      // Check writable
107	      try {
108	        accessSync(dir.path, constants.W_OK);
109	        results.push({
110	          name: dir.name,
111	          passed: true,
112	          message: "exists and writable",
113	        });
114	      } catch {
115	        results.push({
116	          name: dir.name,
117	          passed: false,
118	          message: "exists but not writable",
119	          suggestion: `Check permissions on ${dir.path}`,
120	        });
121	      }
122	    }
123	  }
124	
125	  return results;
126	}
127	
128	function checkConfig(cwd: string): CheckResult {
129	  const configPath = findConfigPath(cwd);
130	
131	  if (!configPath) {
132	    return {
133	      name: "Config",
134	      passed: true, // Not a failure — just not in a project
135	      message: "not found (not in a Corgi project)",
136	    };
137	  }
138	
139	  try {
140	    const config = loadConfig(configPath);
141	    return {
142	      name: "Config",
143	      passed: true,
144	      message: `valid (schema: ${config.schema})`,
145	    };
146	  } catch (err: unknown) {
147	    const msg = err instanceof Error ? err.message : String(err);
148	    return {
149	      name: "Config",
150	      passed: false,
151	      message: msg,
152	      suggestion: "Fix the config.yaml file or run `corgispec init` to recreate it.",
153	    };
154	  }
155	}
156	
157	function checkPlatforms(): CheckResult[] {
158	  const results: CheckResult[] = [];
159	  const platforms = detectPlatforms();
160	  const detected = platforms.filter((p) => p.detected);
161	
162	  if (detected.length === 0) {
163	    results.push({
164	      name: "AI Platforms",
165	      passed: true, // Not a hard failure
166	      message:
167	        "No AI platforms detected. Run `corgispec install` after setting up your platform.",
168	    });
169	  } else {
170	    for (const p of detected) {
171	      results.push({
172	        name: `${p.platform} (platform)`,
173	        passed: true,
174	        message: "detected",
175	      });
176	    }
177	  }
