28	/**
29	 * Install skills to a target directory.
30	 * Source may be tiered (atoms/, molecules/, compounds/) or flat.
31	 * Target is always flat (agent platforms expect flat user-level layout).
32	 */
33	export function installSkillsTo(
34	  sourceDir: string,
35	  targetDir: string,
36	  dryRun: boolean
37	): string[] {
38	  const installed: string[] = [];
39	  const tierDirs = ["atoms", "molecules", "compounds"];
40	
41	  if (!existsSync(sourceDir)) {
42	    return installed;
43	  }
44	
45	  function installEntry(src: string, name: string): void {
