15	const MANIFEST_PATHS = [
16	  "openspec/install-manifest.yaml",
17	  "openspec/.corgi-install.json",
18	] as const;
19	
20	const LEGACY_MARKERS = [
21	  ".opencode/commands/corgi-install.md",
22	  ".claude/commands/corgi/install.md",
23	] as const;
24	
25	export type BootstrapMode =
26	  | "auto"
