44	export interface InstallManifest {
45	  version: number;
46	  schema?: SchemaType;
47	  installedAt?: string;
48	  updatedAt?: string;
49	  managedFiles?: Array<string | InstallManifestFile>;
50	  files?: Record<string, { sha256?: string }>;
51	}
