68	function getAssetsRoot(assetsRoot?: string): string {
69	  if (assetsRoot) {
70	    return assetsRoot;
71	  }
72	
73	  const fromDist = resolve(__dirname, "../assets");
74	  if (existsSync(fromDist)) {
75	    return fromDist;
76	  }
77	
78	  const fromSrc = resolve(__dirname, "../../assets");
79	  if (existsSync(fromSrc)) {
80	    return fromSrc;
81	  }
82	
83	  throw new Error(
84	    "Assets directory not found. Run 'npm run build' or 'node scripts/bundle-assets.js'."
85	  );
86	}
87	
88	function listFiles(rootDir: string): string[] {
89	  if (!existsSync(rootDir)) {
90	    return [];
91	  }
92	
93	  const files: string[] = [];
94	  for (const entry of readdirSync(rootDir, { withFileTypes: true })) {
95	    const fullPath = resolve(rootDir, entry.name);
96	    if (entry.isDirectory()) {
97	      files.push(...listFiles(fullPath));
98	      continue;
99	    }
100	    if (entry.isFile() || statSync(fullPath).isFile()) {
101	      files.push(fullPath);
102	    }
103	  }
104	  return files.sort();
105	}
106	
107	function normalizeRelativePath(path: string): string {
108	  return path.replace(/\\/g, "/");
109	}
110	
111	function parseMaybeYamlOrJson(filePath: string): unknown {
112	  const content = readFileSync(filePath, "utf-8");
113	  if (filePath.endsWith(".json")) {
114	    return JSON.parse(content);
115	  }
116	  return yaml.load(content);
117	}
118	
119	function getManifestPath(targetDir: string): string | undefined {
120	  for (const relativePath of MANIFEST_PATHS) {
121	    const candidate = resolve(targetDir, relativePath);
122	    if (existsSync(candidate)) {
123	      return candidate;
124	    }
125	  }
126	  return undefined;
127	}
128	
129	function readSchemaFromConfig(configPath: string): SchemaType | undefined {
130	  if (!existsSync(configPath)) {
131	    return undefined;
132	  }
133	
134	  const parsed = yaml.load(readFileSync(configPath, "utf-8"));
135	  if (!parsed || typeof parsed !== "object") {
136	    return undefined;
137	  }
138	
139	  const schema = (parsed as Record<string, unknown>).schema;
140	  if (schema === "github-tracked" || schema === "gitlab-tracked") {
141	    return schema;
142	  }
143	
144	  return undefined;
145	}
146	
147	function getManifestManagedFiles(manifestPath: string): string[] {
148	  const parsed = parseMaybeYamlOrJson(manifestPath) as InstallManifest | null;
149	  if (!parsed || typeof parsed !== "object") {
150	    return [];
151	  }
152	
153	  const managedFiles = new Set<string>();
154	
155	  for (const entry of parsed.managedFiles ?? []) {
156	    if (typeof entry === "string") {
157	      managedFiles.add(normalizeRelativePath(entry));
158	      continue;
159	    }
160	
161	    if (entry && typeof entry === "object" && typeof entry.path === "string") {
162	      managedFiles.add(normalizeRelativePath(entry.path));
163	    }
164	  }
165	
166	  for (const key of Object.keys(parsed.files ?? {})) {
167	    managedFiles.add(normalizeRelativePath(key));
168	  }
169	
170	  return Array.from(managedFiles).sort();
171	}
172	
173	function findLegacyManagedFiles(targetDir: string, schema?: SchemaType): string[] {
174	  const candidates = new Set<string>(LEGACY_MARKERS);
175	  if (schema) {
176	    candidates.add(`openspec/schemas/${schema}/schema.yaml`);
177	  }
178	
179	  return Array.from(candidates)
180	    .filter((relativePath) => existsSync(resolve(targetDir, relativePath)))
181	    .sort();
182	}
183	
184	export function classifyTargetState(targetDir: string): TargetState {
185	  const configPath = resolve(targetDir, "openspec/config.yaml");
186	  const hasConfig = existsSync(configPath);
187	  const manifestPath = getManifestPath(targetDir);
188	  const hasManifest = Boolean(manifestPath);
189	  const schema = readSchemaFromConfig(configPath);
190	  const manifestManagedFiles = manifestPath ? getManifestManagedFiles(manifestPath) : [];
191	  const managedFiles = findLegacyManagedFiles(targetDir, schema);
192	
193	  if (hasConfig && manifestPath && manifestManagedFiles.length > 0) {
194	    return {
195	      kind: "managed-update",
196	      hasConfig,
197	      hasManifest,
198	      configPath,
199	      manifestPath,
200	      managedFiles: manifestManagedFiles,
201	    };
202	  }
203	
204	  if (hasManifest) {
205	    return {
206	      kind: "inconsistent",
207	      hasConfig,
208	      hasManifest,
209	      configPath,
210	      manifestPath,
211	      managedFiles: manifestManagedFiles,
212	    };
213	  }
214	
215	  if (hasConfig && managedFiles.length > 0) {
216	    return {
217	      kind: "legacy",
218	      hasConfig,
219	      hasManifest,
220	      configPath,
221	      managedFiles,
222	    };
223	  }
224	
225	  if (managedFiles.length > 0) {
226	    return {
227	      kind: "inconsistent",
228	      hasConfig,
229	      hasManifest,
230	      configPath,
231	      managedFiles,
232	    };
233	  }
234	
235	  return {
236	    kind: hasConfig ? "fresh" : "init-needed",
237	    hasConfig,
238	    hasManifest,
239	    configPath,
240	    managedFiles: [],
241	  };
242	}
243	
244	export function getManagedProjectFiles(
245	  schema: SchemaType,
246	  assetsRoot?: string
247	): string[] {
248	  const root = getAssetsRoot(assetsRoot);
249	  return [
250	    ...listFiles(resolve(root, "commands/opencode")),
251	    ...listFiles(resolve(root, "commands/claude/corgi")),
252	    ...listFiles(resolve(root, "schemas", schema)),
253	  ].sort();
254	}
255	
256	export function patchInstallerConfig(
257	  existingYaml: string,
258	  input: InstallerConfigPatchInput
259	): string {
260	  const parsed = yaml.load(existingYaml);
261	  const existing =
262	    parsed && typeof parsed === "object" ? (parsed as Record<string, unknown>) : {};
263	
264	  const next: Record<string, unknown> = {
265	    ...existing,
266	    schema: input.schema,
267	  };
268	
269	  if (input.isolation !== undefined) {
270	    next.isolation = input.isolation;
271	  }
272	
273	  if (input.installer !== undefined) {
274	    next.installer = input.installer;
275	  }
276	
277	  return yaml.dump(next, {
278	    lineWidth: -1,
279	    noRefs: true,
280	  });
281	}
