283	export function sha256File(filePath: string): string {
284	  return createHash("sha256").update(readFileSync(filePath)).digest("hex");
285	}
286	
287	export function relativeManagedFiles(targetDir: string, files: string[]): string[] {
288	  return files.map((filePath) => normalizeRelativePath(relative(targetDir, filePath)));
289	}
