132	function initPlatformDirs(target: string, platform: PlatformOption): void {
133	  const platforms: string[] =
134	    platform === "all"
135	      ? ["claude", "opencode", "codex"]
136	      : [platform];
137	
138	  for (const p of platforms) {
139	    let dir: string;
140	    switch (p) {
141	      case "claude":
142	        dir = resolve(target, ".claude/skills");
143	        break;
144	      case "opencode":
145	        dir = resolve(target, ".opencode/skills");
146	        break;
147	      case "codex":
148	        dir = resolve(target, ".codex/skills");
149	        break;
150	      default:
151	        continue;
152	    }
153	
154	    if (!existsSync(dir)) {
155	      mkdirSync(dir, { recursive: true });
156	      console.log(`  Created: ${dir}`);
157	    } else {
158	      console.log(`  Exists: ${dir}`);
159	    }
160	  }
161	}
